use vstd::prelude::*;

verus! {
    // A little helper to recognize decimal digits
    spec fn is_digit(c: char) -> bool {
        '0' <= c && c <= '9'
    }

    fn solve(a: i8, b: i8, s: Vec<char>) -> (result: Vec<char>)
        requires
            // the two integers are in [1,5]
            1 <= a && a <= 5,
            1 <= b && b <= 5,
            // the length of s is exactly a + b + 1
            s.len() == (a as usize) + (b as usize) + 1,
            // every character is either a digit or a hyphen
            forall |i: usize| i < s.len() ==> (s[i] == '-' || is_digit(s[i]))
        ensures
            // result is "Yes" exactly when
            //   at index a there is a '-' and
            //   everywhere else a digit
            (forall |i: usize| i < s.len() ==>
                if i == (a as usize) { s[i] == '-' }
                else                  { is_digit(s[i]) }
            )
            <==> result == vec!['Y','e','s']
    {
        let au = a as usize;
        let bu = b as usize;
        let n = au + bu + 1;
        // idx walks 0..n, ok accumulates the conjunction
        let mut idx: usize = 0;
        let mut ok: bool = true;
        while idx < n
            invariant
                idx <= n,
                // ok == forall j < idx. cond(j)
                ok
                    == (forall |j: usize| j < idx ==>
                            if j == au { s[j] == '-' }
                            else        { is_digit(s[j]) }
                       )
            decreases n - idx
        {
            // check the current position
            let cond = if idx == au {
                s[idx] == '-'
            } else {
                is_digit(s[idx])
            };
            ok = ok && cond;
            idx = idx + 1;
        }
        // now idx == n, so ok == forall j < n. cond(j)
        // we return "Yes" exactly when ok is true
        let result = if ok {
            vec!['Y','e','s']
        } else {
            vec!['N','o']
        };
        result
    }
}

